#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<array<double,3>> solve(vector<int>& id, vector<int>& dept, vector<int>& mark) {
        int n = id.size();
        vector<array<double,3>> res;
        for (int i = 0; i < n; i++) {
            set<int> higher; int cnt = 0;
            for (int j = 0; j < n; j++) if (dept[j] == dept[i]) {
                cnt++;
                if (mark[j] > mark[i]) higher.insert(mark[j]);
            }
            double pct = (double)higher.size() * 100.0 / (cnt - 1);
            res.push_back({(double)id[i], (double)dept[i], round(pct * 100) / 100});
        }
        return res;
    }
};

