import java.util.*;
class Solution {
    public List<double[]> solve(int[] id, int[] dept, int[] mark) {
        int n = id.length;
        List<double[]> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Set<Integer> higher = new HashSet<>();
            int cnt = 0;
            for (int j = 0; j < n; j++) if (dept[j] == dept[i]) {
                cnt++;
                if (mark[j] > mark[i]) higher.add(mark[j]);
            }
            double pct = Math.round(higher.size() * 10000.0 / (cnt - 1)) / 100.0;
            res.add(new double[]{id[i], dept[i], pct});
        }
        return res;
    }
}

